import {POEMS,POEM_LINES} from './poetry-data.mjs';
export {POEMS,POEM_LINES};
export const POEM_INDEX=new Map(POEMS.map(p=>[p.id,p]));
export const VERSE_INDEX=new Map(POEM_LINES.map(l=>[l.word,l]));
export const MAX_WORD_LENGTH=7;
export const POETRY_TECHNIQUE_POWER=1.5;
export const POETRY_DRAW_CHANCE=.28;
export const FIELD_INTERVALS={allShield:16,allFreeze:18,allMend:18,allHaste:14,allSlow:12,allSilence:14,allWeaken:12,allReveal:10};
export const POETRY_PALETTES={snow:'#88adbc',ice:'#89adb9',frost:'#93a9b9',moon:'#a49ac3',stars:'#b19e6b',star:'#b8a878',sun:'#b69857',sunset:'#c28c67',dawn:'#c5a464',river:'#588f9c',water:'#639ca3',waterfall:'#619eaf',wave:'#527d9c',ripple:'#78a8a9',rain:'#729e98',spring:'#78a079',leaf:'#7e9873',grass:'#8ba376',petal:'#c08b9f',peach:'#c89399',plum:'#b38b9c',lotus:'#b18fa1',bamboo:'#76916d',mountain:'#8a9685',rock:'#9c947e',fire:'#bc7f54',firecracker:'#b97f56',storm:'#a5915e',jade:'#81a397',heart:'#be9990',resolve:'#b69b70',ink:'#7f91a2',scroll:'#aa9c74'};
export const poemPalette=l=>POETRY_PALETTES[l.art]||'#9e9173';
export const POETRY_WORDS=POEM_LINES.map(l=>({word:l.word,type:'poetry',icon:'诗',name:'诗韵',color:poemPalette(l),poem:l.poem,verse:l.word,tier:l.word.length,maxLevel:l.word.length+2,cost:{5:270,6:330,7:400}[l.word.length],damage:{5:110,6:132,7:154}[l.word.length],range:255+(l.word.length-5)*15,rate:1.35,trait:'balanced',runes:[],aura:0,income:0,tag:'专属诗意绝技',desc:'以墨字攻击单体；每次普攻积蓄 1 点诗韵。蓄满后释放本句独有的诗意绝技。'}));
const pct=n=>Math.round(n*100)+'%';
const opText=([kind,a,b,c])=>({
 strike:()=>`对主目标追击 ${a} 次，每次 ${pct(b*POETRY_TECHNIQUE_POWER)} 攻击伤害`,burst:()=>`墨意在 ${c} 半径内绽开，最多 ${a} 个敌人各受 ${pct(b*POETRY_TECHNIQUE_POWER)} 伤害`,chain:()=>`以 ${c} 距离接续最多 ${a} 个目标，各造成 ${pct(b*POETRY_TECHNIQUE_POWER)} 伤害`,fan:()=>`以 ${(c*180/Math.PI*2).toFixed(0)}° 扇面扫过最多 ${a} 敌人，各造成 ${pct(b*POETRY_TECHNIQUE_POWER)} 伤害`,line:()=>`贯穿宽度 ${c*2} 的墨线，最多 ${a} 个敌人各受 ${pct(b*POETRY_TECHNIQUE_POWER)} 伤害`,sky:()=>`优先追击飞行敌人，最多 ${a} 个各受 ${pct(b*POETRY_TECHNIQUE_POWER)} 伤害`,ground:()=>`拦截最多 ${a} 个地面敌人，各造成 ${pct(b*POETRY_TECHNIQUE_POWER)} 伤害`,slow:()=>`本次命中的敌人减速 ${pct(1-a)}，持续 ${b} 秒`,freeze:()=>`本次命中的敌人冻结 ${a} 秒`,mark:()=>`本次命中的敌人直伤易伤 ${pct(a)}，持续 ${b} 秒`,burn:()=>`本次命中的敌人灼烧 ${b} 秒，每秒 ${pct(a*POETRY_TECHNIQUE_POWER)} 攻击伤害`,silence:()=>`本次命中的敌人缄默 ${a} 秒`,armor:()=>`本次命中的敌人破甲 ${a} 秒`,shred:()=>`本次命中的敌人护盾削减 ${pct(a)}，每名最多削去 3 倍攻击的护盾`,push:()=>`本次命中的敌人沿原路线后退 ${a}；Boss 后退距离为五分之一`,reveal:()=>`本次命中的敌人显形 ${a} 秒`,shield:()=>`为范围内耐久最低的 ${c} 座存活塔提供 ${pct(a)} 最大耐久护盾，持续 ${b} 秒`,heal:()=>`修复范围内耐久最低的 ${b} 座存活塔，各恢复 ${pct(a)} 最大耐久`,haste:()=>`范围内 ${c} 座存活塔攻速提高 ${pct(a)}，持续 ${b} 秒`,guard:()=>`范围内耐久最低的 ${c} 座存活塔承伤降低 ${pct(a)}，持续 ${b} 秒`,allShield:()=>`全场存活词塔获得 ${pct(a)} 最大耐久护盾，持续 ${b} 秒`,allFreeze:()=>`全场敌人冻结 ${a} 秒`,allSlow:()=>`全场敌人减速 ${pct(1-a)}，持续 ${b} 秒`,allMend:()=>`全场存活词塔修复 ${pct(a)} 最大耐久；同时清除寒滞与腐蚀`,allReveal:()=>`全场敌人显形 ${a} 秒，破解潜行`,allHaste:()=>`全场存活词塔攻速提高 ${pct(a)}，持续 ${b} 秒`,allSilence:()=>`全场敌人缄默 ${a} 秒，可打断技能蓄力`,allWeaken:()=>`全场敌人攻塔伤害降低 15%，持续 ${a} 秒`
}[kind]());
export function verseDescription(word){const l=typeof word==='string'?VERSE_INDEX.get(word):word;return `每 ${l.charge} 次普攻蓄满诗韵，绝技冷却 ${l.cooldown} 秒。${l.ops.map(opText).join('；')}。`+(l.field.length?`同类全场效果分别共享施法间隔（${l.field.map(k=>({allShield:'护盾',allFreeze:'冻结',allMend:'修复',allHaste:'攻速',allSlow:'减速',allSilence:'缄默',allWeaken:'削弱',allReveal:'显形'}[k])+' '+FIELD_INTERVALS[k]+' 秒').join('、')}）。`:'');}
export const POETRY_CONTROL_NOTE='冻结与缄默对 Boss 的持续时间为四分之一；同目标冻结后有 6 秒间隔。未破的冰壳免疫冻结与减速。同类护盾、攻速和减伤取最强值，不累加；只能修复存活塔，不恢复爱心或重建废墟。';
export function verseStatus(t,time,fieldReady={}){const l=VERSE_INDEX.get(t.word);return{charge:Math.min(l.charge,t.verseCharge||0),need:l.charge,remaining:Math.max(0,(t.verseReadyAt||0)-time,...l.field.map(k=>(fieldReady[k]||0)-time))};}
